import itertools

n = 10
elements = list(range(1, n + 1))
total_sum = n * (n + 1) // 2
# The largest possible prefix sum is 55. Squares to avoid are 1, 4, 9, 16, 25, 36, 49.
forbidden_squares = {i*i for i in range(1, int(total_sum)**0.5 + 1)}
print(f"Total sum: {total_sum}. Forbidden squares: {forbidden_squares}")

def is_cool_permutation(perm, forbidden):
    current_sum = 0
    for i in range(n):
        current_sum += perm[i]
        if current_sum in forbidden:
            return False
    return True

found_cool = False
# Check all 10! permutations
for perm in itertools.permutations(elements):
    if is_cool_permutation(perm, forbidden_squares):
        print(f"Found cool permutation: {perm}")
        found_cool = True
        break

if not found_cool:
    print("No cool permutation found for n=10.")

