import math

def is_square(n):
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def is_cool(N):
    # Backtracking function
    # current_sum: The sum of elements chosen so far
    # used: A set of numbers already used in the permutation
    def backtrack(current_sum, used):
        # If we successfully placed N elements, it's cool
        if len(used) == N:
            return True

        # Try all available numbers
        for x in range(1, N + 1):
            if x not in used:
                next_sum = current_sum + x

                # Check the cool condition: next_sum must not be a perfect square
                if not is_square(next_sum):
                    used.add(x)
                    if backtrack(next_sum, used):
                        return True
                    # Backtrack step
                    used.remove(x)

        return False

    # Start the search. Initial sum is 0, nothing is used.
    # We need to check all possible starting points x_1 since x_1 itself is S_1.
    for x1 in range(1, N + 1):
        if not is_square(x1):
            # Start a new search for this x1
            if backtrack(x1, {x1}):
                return True

    return False

# --- Task Implementation ---
# 1. Exhaustive search up to N=100
N_limit = 100
cool_integers_up_to_100 = {}
print("--- Coolness Search Results (N=1 to 100) ---")

for N in range(1, N_limit + 1):
    try:
        result = is_cool(N)
        cool_integers_up_to_100[N] = result
        print(f"N={N:3d}: {'COOL' if result else 'NOT COOL'}")
    except RecursionError:
        print(f"N={N:3d}: RECURSION LIMIT HIT (Search too deep/slow)")

# 2. Specific checks around N=49 and N=288
special_checks = [48, 50, 287, 289]
