            result = is_cool(N)
            print(f"N={N:3d}: {'COOL' if result else 'NOT COOL'}")
        except RecursionError:
            print(f"N={N:3d}: RECURSION LIMIT HIT")
    else:
        print(f"N={N:3d}: Outside current search range.")

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

def is_cool(n):
    if n == 0:
        return False

    # Backtracking function
    def solve(current_sum, remaining_numbers, path_length):
        if path_length == n:
            return True  # Found a valid permutation

        for i in range(len(remaining_numbers)):
            next_x = remaining_numbers[i]
            next_sum = current_sum + next_x

            if not is_square(next_sum):
                # Create new set of remaining numbers
                new_remaining = remaining_numbers[:i] + remaining_numbers[i+1:]

                if solve(next_sum, new_remaining, path_length + 1):
                    return True

        return False

    # Initial state: current_sum = 0, remaining_numbers = list(range(1, n + 1)), path_length = 0
    # The first element x_1 cannot be a square.

    initial_numbers = list(range(1, n + 1))

    for i in range(n):
        x1 = initial_numbers[i]
        if not is_square(x1):
            remaining = initial_numbers[:i] + initial_numbers[i+1:]
            if solve(x1, remaining, 1):
                return True

    return False

# Test range N=1 to N=50
results = {}
for n in range(1, 51):
    results[n] = is_cool(n)

# Print the results in a structured way
print("N | Cool?")
print("--------------------")
for n in range(1, 51):
    print(f"{n:2} | {results[n]}")

